from collections import deque

# Read input
n, m = map(int, input().split())
field = [input().strip() for _ in range(n)]

# Directions for BFS
directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

# Function to check if a cell is within bounds
def is_valid(x, y):
    return 0 <= x < n and 0 <= y < m

# Function to perform BFS and find the component size
def bfs(x, y, visited):
    queue = deque([(x, y)])
    visited[x][y] = True
    component_size = 0
    while queue:
        cx, cy = queue.popleft()
        component_size += 1
        for dx, dy in directions:
            nx, ny = cx + dx, cy + dy
            if is_valid(nx, ny) and not visited[nx][ny] and field[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny))
    return component_size

# Check if the field can be filled
def can_fill_field(field):
    visited = [[False] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if field[i][j] == '#' and not visited[i][j]:
                component_size = bfs(i, j, visited)
                if component_size == 1:
                    return False
    return True

# If the field cannot be filled, return -1
if not can_fill_field(field):
    print(-1)
    sys.exit()

# Create a copy of the field to fill
filled_field = [list(row) for row in field]

# Assign digits to each component
